public class Main {
    // each process in iteration i becomes two: parent and child both keep looping
    static int everyProcessForks(int i, int n) {
        return i == n ? 1 : 2 * everyProcessForks(i + 1, n);
    }

    // the child leaves the loop right away, only the parent keeps forking
    static int onlyParentForks(int i, int n) {
        return i == n ? 1 : 1 + onlyParentForks(i + 1, n);
    }

    public static void main(String[] args) {
        for (int n = 1; n <= 4; n++) {
            System.out.println("n=" + n + "  everyone forks: " + everyProcessForks(0, n)
                + " processes, only parent forks: " + onlyParentForks(0, n) + " processes");
        }
        // fork() && fork(): the child of the first fork gets 0, so it skips the second
        System.out.println("fork() && fork(): 3 processes");
    }
}

